  function sanitizeRecord(raw,def,seq){const r=freshRecord();if(!plain(raw))return r;const choiceCount=def.choices?.length||0;r.choice=choiceCount&&Number.isInteger(raw.choice)&&raw.choice>=0&&raw.choice<choiceCount?raw.choice:null;if(!['active','ready','completed'].includes(raw.status)||!Number.isFinite(raw.acceptedAt)||raw.acceptedAt<0||choiceCount&&r.choice===null){r.choice=null;return r;}r.acceptedAt=Math.min(seq,number(raw.acceptedAt));r.paid=raw.status==='completed';r.counts=Object.fromEntries(objectives(def,r).map(g=>[g.id,r.paid?g.goal:number(raw.counts?.[g.id],g.goal)]));r.status=r.paid?'completed':complete(def,r)?'ready':'active';return r;}
